package dev.interfacehotkeyguard;

import com.google.inject.Provides;
import java.awt.event.KeyEvent;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(
	name = "Interface Hotkey Guard",
	description = "Suppresses selected hotkeys while certain interfaces are open"
)
public class InterfaceHotkeyGuardPlugin extends Plugin
{
	// Migrate saved preferences from the plugin's original config group.
	private static final String LEGACY_CONFIG_GROUP = "bankinventorytoggleguard";
	private static final String[] CONFIG_KEYS = {
		"protectBank", "protectCollectionLog", "protectSettings",
		"suppressF1", "suppressF2", "suppressF3", "suppressF4",
		"suppressF5", "suppressF6", "suppressF7", "suppressF8",
		"suppressF9", "suppressF10", "suppressF11", "suppressF12"
	};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private KeyManager keyManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private InterfaceHotkeyGuardConfig config;

	private final InterfaceState interfaceState = new InterfaceState();

	private final KeyListener inputListener = new KeyListener()
	{
		@Override
		public void keyPressed(KeyEvent event)
		{
			if (interfaceState.shouldSuppress(
				config.protectBank(), config.protectCollectionLog(), config.protectSettings())
				&& FunctionKeyFilter.shouldSuppress(event.getKeyCode(), event.getModifiersEx(), config))
			{
				event.consume();
			}
		}

		@Override
		public void keyTyped(KeyEvent event)
		{
		}

		@Override
		public void keyReleased(KeyEvent event)
		{
		}

		@Override
		public void focusLost()
		{
		}
	};

	@Provides
	InterfaceHotkeyGuardConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(InterfaceHotkeyGuardConfig.class);
	}

	@Override
	protected void startUp()
	{
		migrateConfiguration();
		interfaceState.beginInitialization();
		keyManager.registerKeyListener(inputListener);
		clientThread.invokeLater(() ->
		{
			interfaceState.initialize(
				client.getWidget(InterfaceID.Bankmain.UNIVERSE) != null,
				client.getWidget(InterfaceID.Collection.FRAME) != null,
				client.getWidget(InterfaceID.Settings.UNIVERSE) != null);
		});
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(inputListener);
		interfaceState.reset();
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		interfaceState.onWidgetLoaded(event.getGroupId());
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		interfaceState.onWidgetClosed(event.getGroupId());
	}

	private void migrateConfiguration()
	{
		for (String key : CONFIG_KEYS)
		{
			if (configManager.getConfiguration(InterfaceHotkeyGuardConfig.CONFIG_GROUP, key) != null)
			{
				continue;
			}

			String oldValue = configManager.getConfiguration(LEGACY_CONFIG_GROUP, key);
			if (oldValue != null)
			{
				configManager.setConfiguration(InterfaceHotkeyGuardConfig.CONFIG_GROUP, key, oldValue);
			}
		}
	}
}

package dev.interfacehotkeyguard;

import net.runelite.api.gameval.InterfaceID;

final class InterfaceState
{
	private static final int BANK_GROUP_ID = InterfaceID.BANKMAIN;
	private static final int COLLECTION_LOG_GROUP_ID = InterfaceID.COLLECTION;
	private static final int SETTINGS_GROUP_ID = InterfaceID.SETTINGS;

	private volatile boolean initialized;
	private volatile boolean bankOpen;
	private volatile boolean collectionLogOpen;
	private volatile boolean settingsOpen;

	void beginInitialization()
	{
		bankOpen = false;
		collectionLogOpen = false;
		settingsOpen = false;
		initialized = false;
	}

	void initialize(boolean bankOpen, boolean collectionLogOpen, boolean settingsOpen)
	{
		this.bankOpen = bankOpen;
		this.collectionLogOpen = collectionLogOpen;
		this.settingsOpen = settingsOpen;
		initialized = true;
	}

	void reset()
	{
		initialize(false, false, false);
	}

	void onWidgetLoaded(int groupId)
	{
		if (groupId == BANK_GROUP_ID)
		{
			bankOpen = true;
		}
		else if (groupId == COLLECTION_LOG_GROUP_ID)
		{
			collectionLogOpen = true;
		}
		else if (groupId == SETTINGS_GROUP_ID)
		{
			settingsOpen = true;
		}
	}

	void onWidgetClosed(int groupId)
	{
		if (groupId == BANK_GROUP_ID)
		{
			bankOpen = false;
		}
		else if (groupId == COLLECTION_LOG_GROUP_ID)
		{
			collectionLogOpen = false;
		}
		else if (groupId == SETTINGS_GROUP_ID)
		{
			settingsOpen = false;
		}
	}

	boolean shouldSuppress(boolean protectBank, boolean protectCollectionLog, boolean protectSettings)
	{
		if (!initialized)
		{
			return protectBank || protectCollectionLog || protectSettings;
		}

		return (protectBank && bankOpen)
			|| (protectCollectionLog && collectionLogOpen)
			|| (protectSettings && settingsOpen);
	}
}

package dev.interfacehotkeyguard;

import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class FunctionKeyFilterTest
{
	@Test
	public void selectsConfiguredFunctionKeys()
	{
		InterfaceHotkeyGuardConfig config = new InterfaceHotkeyGuardConfig() {};
		int[] functionKeys = {
			KeyEvent.VK_F1, KeyEvent.VK_F2, KeyEvent.VK_F3, KeyEvent.VK_F4,
			KeyEvent.VK_F5, KeyEvent.VK_F6, KeyEvent.VK_F7, KeyEvent.VK_F8,
			KeyEvent.VK_F9, KeyEvent.VK_F10, KeyEvent.VK_F11, KeyEvent.VK_F12
		};

		for (int keyCode : functionKeys)
		{
			assertTrue("Expected F-key to be selected: " + keyCode,
				FunctionKeyFilter.shouldSuppress(keyCode, 0, config));
		}

		assertFalse(FunctionKeyFilter.shouldSuppress(KeyEvent.VK_A, 0, config));
	}

	@Test
	public void leavesUnselectedFunctionKeyAlone()
	{
		InterfaceHotkeyGuardConfig config = new InterfaceHotkeyGuardConfig()
		{
			@Override
			public boolean suppressF2()
			{
				return false;
			}
		};

		assertFalse(FunctionKeyFilter.shouldSuppress(KeyEvent.VK_F2, 0, config));
	}

	@Test
	public void allowsModifiedFunctionKeys()
	{
		InterfaceHotkeyGuardConfig config = new InterfaceHotkeyGuardConfig() {};
		int[] modifiers = {
			InputEvent.SHIFT_DOWN_MASK,
			InputEvent.CTRL_DOWN_MASK,
			InputEvent.ALT_DOWN_MASK,
			InputEvent.META_DOWN_MASK,
			InputEvent.ALT_GRAPH_DOWN_MASK,
			InputEvent.CTRL_DOWN_MASK | InputEvent.SHIFT_DOWN_MASK
		};

		for (int modifier : modifiers)
		{
			assertFalse("Expected modifier combination to pass through: " + modifier,
				FunctionKeyFilter.shouldSuppress(KeyEvent.VK_F2, modifier, config));
		}
	}
}

